tasks.tests:
assert($('h1'), 'На странице нет тега h1');
equal(text('h1'), 'Азиз', 'Текст заголовка');
assert($('p'), 'Не хватает абзаца <p>');
assert(text('p').length > 0, 'Абзац пустой — напиши в нём хоть что-нибудь');

assert($('ul'), 'Нужен маркированный список <ul>');
equal($$('ul li').length, 3, 'Количество пунктов в списке');
var a = $('a');
assert(a, 'Не хватает ссылки <a>');
equal(a.getAttribute('href'), 'https://developer.mozilla.org', 'Адрес в href');

assert($('header'), 'Нет <header>');
assert($('header h1'), 'Внутри <header> должен быть <h1>');
assert($('header nav'), 'Внутри <header> должен быть <nav>');
equal($$('header nav a').length, 2, 'Ссылок в навигации');
assert($('main'), 'Нет <main>');
assert($('main p'), 'Внутри <main> должен быть абзац <p>');
assert($('footer'), 'Нет <footer>');

assert($('article'), 'Нет <article>');
assert($('article h2'), 'Внутри article нужен <h2>');
assert($('article p'), 'Внутри article нужен абзац');
var img = $('article img');
assert(img, 'Внутри article нужна картинка <img>');
assert((img.getAttribute('alt') || '').trim().length > 0, 'У картинки должен быть непустой alt');

assert($('form'), 'Нет тега <form>');
const inp = $('form input#mail');
assert(inp, 'Нужно поле с id="mail"');
equal(inp.getAttribute('type'), 'email', 'Тип поля');
const lab = $('form label');
assert(lab, 'Не хватает подписи <label>');
equal(lab.getAttribute('for'), 'mail', 'label должен быть связан с полем через for');
assert($('form button') || $('form input[type="submit"]'), 'Нужна кнопка отправки');

assert($('table'), 'Нет тега <table>');
assert($('table thead'), 'Нужен <thead>');
equal($$('table thead th').length, 2, 'Заголовков в шапке');
assert($('table tbody'), 'Нужен <tbody>');
equal($$('table tbody tr').length, 2, 'Строк в теле таблицы');
equal($$('table tbody td').length, 4, 'Всего ячеек в теле (2 строки × 2)');

assert($('article'), 'Нет <article>');
assert($('article h2'), 'Нужен заголовок <h2>');
const img = $('article img');
assert(img, 'Нужна картинка <img>');
assert((img.getAttribute('alt') || '').trim().length > 0, 'У картинки должен быть непустой alt');
const btn = $('article button');
assert(btn, 'Нужна настоящая кнопка <button>, а не div');
assert(text(btn).length > 0, 'У кнопки должен быть текст');

assert($('form'), 'Нет <form>');
equal($$('form label').length, 3, 'Подписей должно быть три');
const nm = $('#nm'), em = $('#em'), msg = $('#msg');
assert(nm && em, 'Нужны поля с id nm и em');
equal(em.getAttribute('type'), 'email', 'Тип поля почты');
assert(msg && msg.tagName.toLowerCase() === 'textarea', 'Сообщение должно быть <textarea id="msg">');
const fors = $$('form label').map(l => l.getAttribute('for')).sort();
equal(fors, ['em', 'msg', 'nm'], 'Каждая подпись связана со своим полем через for');
assert($('form button') || $('form input[type="submit"]'), 'Нужна кнопка отправки');

var img = $('figure img');
assert(img, 'Нет картинки внутри figure');
equal(img.getAttribute('src'), 'chart.png', 'src картинки');
assert(img.getAttribute('alt') && img.getAttribute('alt').length > 3, 'alt должен быть осмысленным, а не пустым');
equal(img.getAttribute('width'), '640', 'Атрибут width');
equal(img.getAttribute('height'), '360', 'Атрибут height');
equal(img.getAttribute('loading'), 'lazy', 'Атрибут loading');
var cap = $('figure figcaption');
assert(cap && cap.textContent.trim().length > 0, 'figcaption не должен быть пустым');

var v = $('video');
assert(v, 'Нет тега video');
assert(v.hasAttribute('controls'), 'Нужен атрибут controls');
var sources = $$('video source');
equal(sources.length, 2, 'Количество source');
var srcs = sources.map(function(s){ return s.getAttribute('src'); });
assert(srcs.indexOf('lesson.webm') !== -1, 'Нет source с lesson.webm');
assert(srcs.indexOf('lesson.mp4') !== -1, 'Нет source с lesson.mp4');
var track = $('video track');
assert(track, 'Нет тега track');
equal(track.getAttribute('kind'), 'captions', 'kind у track');
equal(track.getAttribute('src'), 'ru.vtt', 'src у track');
equal(track.getAttribute('srclang'), 'ru', 'srclang у track');
assert($('video a'), 'Нужна запасная ссылка на скачивание внутри video');

var f = $('iframe');
assert(f, 'Нет тега iframe');
equal(f.getAttribute('src'), 'https://example.com/map', 'Адрес iframe');
equal(f.getAttribute('width'), '600', 'Ширина');
equal(f.getAttribute('height'), '400', 'Высота');
assert(f.getAttribute('title') && f.getAttribute('title').length > 2, 'Нужен осмысленный title');
equal(f.getAttribute('loading'), 'lazy', 'Атрибут loading');
equal(f.getAttribute('sandbox'), 'allow-scripts', 'Атрибут sandbox');

var art = $('article');
assert(art, 'Нет тега article');
assert($('article h2') && $('article h2').textContent.trim(), 'Нужен непустой h2');
var img = $('article figure img');
assert(img, 'Картинка должна лежать внутри figure');
equal(img.getAttribute('src'), 'cover.jpg', 'src картинки');
assert(img.getAttribute('alt') && img.getAttribute('alt').length > 3, 'Осмысленный alt');
equal(img.getAttribute('width'), '800', 'width');
equal(img.getAttribute('height'), '450', 'height');
equal(img.getAttribute('loading'), 'lazy', 'loading');
assert($('article figure figcaption'), 'Нужен figcaption');
assert($('article p') && $('article p').textContent.trim(), 'Нужен непустой абзац');
var a = $('article a');
assert(a, 'Нужна ссылка');
equal(a.getAttribute('href'), '/article/1', 'Адрес ссылки');
